CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,avatar_asset_id TEXT,preferences_json TEXT NOT NULL DEFAULT '{}',active_workspace_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('personal','team')),is_demo INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,archived_at TEXT);
CREATE TABLE memberships (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','admin','member','viewer')),credit_limit INTEGER CHECK(credit_limit IS NULL OR credit_limit>=0),nickname TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,user_id));
CREATE UNIQUE INDEX workspace_one_owner ON memberships(workspace_id) WHERE role='owner';
CREATE TABLE sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE invitations (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),email TEXT NOT NULL COLLATE NOCASE,role TEXT NOT NULL CHECK(role IN ('admin','member','viewer')),token_hash TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT,revoked_at TEXT);
CREATE TABLE projects (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('image','video','mixed')),cover_asset_id TEXT,document_id TEXT NOT NULL,tags_json TEXT NOT NULL DEFAULT '[]',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE INDEX projects_workspace ON projects(workspace_id,updated_at,id);
CREATE TABLE documents (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),project_id TEXT NOT NULL UNIQUE REFERENCES projects(id),name TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=1),schema_version INTEGER NOT NULL DEFAULT 1,scene_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE document_versions (id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),revision INTEGER NOT NULL,scene_json TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),source_job_id TEXT,restored_from_revision INTEGER,created_at TEXT NOT NULL,UNIQUE(document_id,revision));
CREATE TABLE assets (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),project_id TEXT REFERENCES projects(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('image','video','audio','document')),mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL CHECK(byte_size>0),width INTEGER,height INTEGER,duration_ms REAL,source TEXT NOT NULL,source_job_id TEXT,tags_json TEXT NOT NULL DEFAULT '[]',sha256 TEXT NOT NULL,extraction_status TEXT NOT NULL DEFAULT 'not-applicable',extracted_text TEXT,extraction_error_json TEXT,extraction_truncated INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE INDEX assets_workspace ON assets(workspace_id,created_at,id);
CREATE INDEX assets_extraction ON assets(extraction_status);
CREATE TABLE asset_variants (id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),variant TEXT NOT NULL CHECK(variant IN ('original','preview','thumbnail')),storage_key TEXT NOT NULL,mime_type TEXT NOT NULL,byte_size INTEGER NOT NULL,width INTEGER,height INTEGER,UNIQUE(asset_id,variant));
CREATE TABLE favorites (user_id TEXT NOT NULL REFERENCES users(id),workspace_id TEXT NOT NULL REFERENCES workspaces(id),resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(user_id,resource_type,resource_id));
CREATE TABLE collections (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE asset_collections (collection_id TEXT NOT NULL REFERENCES collections(id),asset_id TEXT NOT NULL REFERENCES assets(id),PRIMARY KEY(collection_id,asset_id));
CREATE TABLE brands (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',colors_json TEXT NOT NULL DEFAULT '[]',fonts_json TEXT NOT NULL DEFAULT '[]',cover_asset_id TEXT,visibility TEXT NOT NULL DEFAULT 'workspace',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE brand_references (brand_id TEXT NOT NULL REFERENCES brands(id),asset_id TEXT NOT NULL REFERENCES assets(id),position INTEGER NOT NULL,PRIMARY KEY(brand_id,asset_id));
CREATE TABLE character_profiles (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',reference_asset_ids_json TEXT NOT NULL DEFAULT '[]',cover_asset_id TEXT,verification_status TEXT NOT NULL DEFAULT 'unverified',verification_provider_id TEXT,verification_expires_at TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE api_keys (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),created_by TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,prefix TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,scopes_json TEXT NOT NULL,credit_limit INTEGER,created_at TEXT NOT NULL,last_used_at TEXT,expires_at TEXT,revoked_at TEXT);
CREATE TABLE audit_events (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,details_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,message TEXT NOT NULL,event_key TEXT UNIQUE,read_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE plans (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,price_minor INTEGER NOT NULL CHECK(price_minor>=0),currency TEXT NOT NULL DEFAULT 'CNY',interval TEXT,credits INTEGER NOT NULL DEFAULT 0,limits_json TEXT NOT NULL DEFAULT '{}',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE orders (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),number TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','pending','paid','failed','cancelled','refunded')),amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,plan_id TEXT REFERENCES plans(id),plan_snapshot_json TEXT NOT NULL,provider_id TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,paid_at TEXT);
CREATE TABLE subscriptions (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),plan_id TEXT NOT NULL REFERENCES plans(id),status TEXT NOT NULL,current_period_start TEXT,current_period_end TEXT,cancel_at_period_end INTEGER NOT NULL DEFAULT 0,provider_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE invoice_titles (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),type TEXT NOT NULL,name TEXT NOT NULL,tax_id TEXT,email TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT);
CREATE TABLE invoice_requests (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title_snapshot_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,provider_id TEXT,download_storage_key TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE invoice_orders (invoice_id TEXT NOT NULL REFERENCES invoice_requests(id),order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),PRIMARY KEY(invoice_id,order_id));
CREATE TABLE support_tickets (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),created_by TEXT NOT NULL REFERENCES users(id),subject TEXT NOT NULL,category TEXT NOT NULL,message TEXT NOT NULL,job_id TEXT,asset_ids_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE ticket_messages (id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES support_tickets(id),user_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE referrals (id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id),code TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE referral_events (id TEXT PRIMARY KEY,referral_id TEXT NOT NULL REFERENCES referrals(id),event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,reward_credits INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE shares (id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),project_id TEXT NOT NULL REFERENCES projects(id),token_hash TEXT NOT NULL UNIQUE,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT);
